import { describe, test, expect } from 'bun:test';
import { sha3 } from './sha3.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha3 = sha3.factory(_ba, _utf8);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));

describe('sha3 module (FIPS 202)', () => {

    test('module metadata', () => {
        expect(sha3.name).toBe('sha3');
        expect(sha3.dependencies).toEqual(['bitArray', 'utf8']);
    });

    // Empty-input vectors (FIPS 202 / NIST CAVP).
    describe('empty input', () => {
        test('SHA3-224("")', () => {
            expect(toHex(_sha3.sha3_224(''))).toBe(
                '6b4e03423667dbb73b6e15454f0eb1abd4597f9a1b078e3f5b5a6bc7'
            );
        });
        test('SHA3-256("")', () => {
            expect(toHex(_sha3.sha3_256(''))).toBe(
                'a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a'
            );
        });
        test('SHA3-384("")', () => {
            expect(toHex(_sha3.sha3_384(''))).toBe(
                '0c63a75b845e4f7d01107d852e4c2485c51a50aaaa94fc61995e71bbee983a2ac3713831264adb47fb6bd1e058d5f004'
            );
        });
        test('SHA3-512("")', () => {
            expect(toHex(_sha3.sha3_512(''))).toBe(
                'a69f73cca23a9ac5c8b567dc185a756e97c982164fe25859e0d1dcc1475c80a615b2123af1f5f94c11e3e9402c3ac558f500199d95b6d3e301758586281dcd26'
            );
        });
    });

    describe('"abc" input', () => {
        test('SHA3-224("abc")', () => {
            expect(toHex(_sha3.sha3_224('abc'))).toBe(
                'e642824c3f8cf24ad09234ee7d3c766fc9a3a5168d0c94ad73b46fdf'
            );
        });
        test('SHA3-256("abc")', () => {
            expect(toHex(_sha3.sha3_256('abc'))).toBe(
                '3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532'
            );
        });
        test('SHA3-384("abc")', () => {
            expect(toHex(_sha3.sha3_384('abc'))).toBe(
                'ec01498288516fc926459f58e2c6ad8df9b473cb0fc08c2596da7cf0e49be4b298d88cea927ac7f539f1edf228376d25'
            );
        });
        test('SHA3-512("abc")', () => {
            expect(toHex(_sha3.sha3_512('abc'))).toBe(
                'b751850b1a57168a5693cd924b6b096e08f621827444f70d884f5d0240d2712e10e116e9192af3c91a7ec57647e3934057340b4cf408d5a56592f8274eec53f0'
            );
        });
    });

    describe('SHAKE empty input (256-bit output)', () => {
        test('SHAKE128("", 256)', () => {
            expect(toHex(_sha3.shake128('', 256))).toBe(
                '7f9c2ba4e88f827d616045507605853ed73b8093f6efbc88eb1a6eacfa66ef26'
            );
        });
        test('SHAKE256("", 512)', () => {
            expect(toHex(_sha3.shake256('', 512))).toBe(
                '46b9dd2b0ba88d13233b3feb743eeb243fcd52ea62b81b82b50c27646ed5762fd75dc4ddd8c0f200cb05019d67b592f6fc821c49479ab48640292eacb3b7c4be'
            );
        });
    });

    describe('200 bytes of 0xa3 (NIST KAT, 1600-bit input)', () => {
        const msg = new Uint8Array(200).fill(0xa3);
        test('SHA3-256', () => {
            expect(toHex(_sha3.sha3_256(msg))).toBe(
                '79f38adec5c20307a98ef76e8324afbfd46cfd81b22e3973c65fa1bd9de31787'
            );
        });
        test('SHA3-512', () => {
            expect(toHex(_sha3.sha3_512(msg))).toBe(
                'e76dfad22084a8b1467fcf2ffa58361bec7628edf5f3fdc0e4805dc48caeeca81b7c13c30adf52a3659584739a2df46be589c51ca1a4a8416df6545a1ce8ba00'
            );
        });
    });

    describe('error handling', () => {
        test('SHAKE rejects non-byte-aligned output', () => {
            expect(_sha3.shake128('', 7)).toBe(false);
        });
    });
});

// ============================================================================
// ACVP SHA3 + SHAKE (NIST CAVP vectors)
// ----------------------------------------------------------------------------
// Sources: references/NIST/ACVP-Server-1.1.0.42/gen-val/json-files/
//   SHA3-{224,256,384,512}-2.0/  (AFT + standard MCT, mctVersion="standard")
//   SHAKE-{128,256}-FIPS202/     (AFT only -- FIPS202 revision has no MCT)
// Coverage strategy:
//   - SHA3 AFT : sub-sampled every 64th tcId + len=0 + min/max len + a few
//                small bit-level anchors. Cap 32000 bits per vector to keep
//                the test file size bounded.
//   - SHA3 MCT : standard algorithm (digestSize seed -> MSG=MD[i-1] -> MD).
//                100 outer x 1000 inner. ALL 100 expected MD asserted
//                byte-exact for SHA3-256 (representative). For 224/384/512
//                we run the MCT but assert only iter0 + iter99 to keep CI
//                under budget; the algorithm path is identical.
//   - SHAKE AFT : sub-sampled every 16th + min/max outLen. Each tcId has
//                 its own outLen (variable XOF output length).
//   - SHAKE MCT : not provided by FIPS202 ACVP revision (per spec).
//   - LDT       : not integrated (multi-GB messages).
// All vectors decoded via bitArray.clamp(ui8_to_ba(bytes), bitLen).
// ============================================================================

const haxToBitsBA = (hexStr, bitLen) => {
    if (bitLen === 0) return [];
    const bytes = _hex.toBytes(hexStr);
    const ba = _ba.ui8_to_ba(bytes);
    return _ba.clamp(ba, bitLen);
};

