describe('sha3 - ACVP SHA3-224-2.0', () => {

    describe('AFT vectors (sub-sampled)', () => {
        test.each(SHA3_224_AFT)('tcId=$tc (len=$len bits)', (vec) => {
            const ba = haxToBitsBA(vec.msg, vec.len);
            expect(_ba.bitLength(ba)).toBe(vec.len);
            expect(toHex(_sha3.sha3_224(ba))).toBe(vec.md.toLowerCase());
        });
    });

    describe('MCT (standard, seedLen=digestSize)', () => {
        // Iteration H2 - assert all 100 iters byte-exact (previously
        // iter0 + iter99 only). Compute cost identical (the hot path
        // remains 100×1000 hashes); adds just 98 assertions.
        test('100 outer x 1000 inner -- all 100 byte-exact', () => {
            const seedBytes = _hex.toBytes(SHA3_224_MCT_SEED_HEX);
            expect(seedBytes.length * 8).toBe(SHA3_224_MCT_SEED_LEN);
            let MD = seedBytes;
            for (let j = 0; j < 100; j++) {
                for (let i = 0; i < 1000; i++) {
                    MD = _ba.ba_to_ui8(_sha3.sha3_224(_ba.ui8_to_ba(MD)));
                }
                expect(_hex.fromBytes(MD)).toBe(SHA3_224_MCT_EXPECTED[j].toLowerCase());
            }
        }, 240_000);
    });

});


