// ============================================================================
// Streaming API (HMAC/HKDF/PBKDF2-compatible)
// ----------------------------------------------------------------------------
// Validates the new `sha3_{224,256,384,512}_hash` submodules that expose the
// `{ name, fn, hash }` shape with `fn.prototype.{blockSize, update, finalize}`
// - the contract that `hash/hmac.js` requires (cf. hmac.js:22-45).
// ============================================================================

describe('sha3 streaming API (HMAC contract)', () => {

    // [variant, expectedBlockSizeBits, oneShotCallable, streamingModule]
    const VARIANTS = [
        ['SHA3-224', 1152, _sha3.sha3_224, _sha3.sha3_224_hash],
        ['SHA3-256', 1088, _sha3.sha3_256, _sha3.sha3_256_hash],
        ['SHA3-384',  832, _sha3.sha3_384, _sha3.sha3_384_hash],
        ['SHA3-512',  576, _sha3.sha3_512, _sha3.sha3_512_hash]
    ];

    test.each(VARIANTS)('%s - module shape: { name, fn, hash } + fn.prototype.{blockSize,update,finalize}',
        (name, bs, oneShot, mod) => {
            expect(mod.name).toBeDefined();
            expect(typeof mod.hash).toBe('function');
            expect(typeof mod.fn).toBe('function');
            expect(mod.fn.prototype.blockSize).toBe(bs);
            expect(typeof mod.fn.prototype.update).toBe('function');
            expect(typeof mod.fn.prototype.finalize).toBe('function');
        });

    test.each(VARIANTS)('%s - streaming one-shot equals callable: hash("abc")',
        (name, bs, oneShot, mod) => {
            const ref = toHex(oneShot('abc'));
            const h = new mod.fn();
            h.update('abc');
            expect(toHex(h.finalize())).toBe(ref);
            // Also via mod.hash (one-shot callable wrapper) - must equal too.
            expect(toHex(mod.hash('abc'))).toBe(ref);
        });

    test.each(VARIANTS)('%s - multi-chunk streaming equals one-shot (300 bytes, 3 chunks)',
        (name, bs, oneShot, mod) => {
            const data = new Uint8Array(300);
            for (let i = 0; i < 300; i++) data[i] = (i * 31 + 7) & 0xff;
            const ref = toHex(oneShot(data));
            const h = new mod.fn();
            h.update(data.subarray(0, 100));
            h.update(data.subarray(100, 250));
            h.update(data.subarray(250));
            expect(toHex(h.finalize())).toBe(ref);
        });

    test.each(VARIANTS)('%s - streaming across exact rate boundary equals one-shot',
        (name, bs, oneShot, mod) => {
            const rateBytes = bs / 8;
            // 3 full rate blocks + 1 byte (forces final partial block + carry)
            const data = new Uint8Array(rateBytes * 3 + 1);
            for (let i = 0; i < data.length; i++) data[i] = i & 0xff;
            const ref = toHex(oneShot(data));
            const h = new mod.fn();
            for (let off = 0; off < data.length; off += rateBytes) {
                h.update(data.subarray(off, Math.min(off + rateBytes, data.length)));
            }
            expect(toHex(h.finalize())).toBe(ref);
        });

    test.each(VARIANTS)('%s - byte-by-byte streaming equals one-shot',
        (name, bs, oneShot, mod) => {
            const data = new TextEncoder().encode('streaming sha3 byte by byte test vector');
            const ref = toHex(oneShot(data));
            const h = new mod.fn();
            for (let i = 0; i < data.length; i++) h.update(data.subarray(i, i + 1));
            expect(toHex(h.finalize())).toBe(ref);
        });

    test.each(VARIANTS)('%s - clone constructor copies state independently',
        (name, bs, oneShot, mod) => {
            const h1 = new mod.fn();
            h1.update('shared prefix - ');
            const h2 = new mod.fn(h1);  // clone
            // Diverge: h1 takes one continuation, h2 another.
            h1.update('branch A');
            h2.update('branch B');
            const out1 = toHex(h1.finalize());
            const out2 = toHex(h2.finalize());
            expect(out1).not.toBe(out2);
            // Cross-check: each branch matches the corresponding one-shot.
            expect(out1).toBe(toHex(oneShot('shared prefix - branch A')));
            expect(out2).toBe(toHex(oneShot('shared prefix - branch B')));
        });

    test.each(VARIANTS)('%s - finalize is one-shot (second call rejected)',
        (name, bs, oneShot, mod) => {
            const h = new mod.fn();
            h.update('once');
            const d1 = h.finalize();
            expect(d1).not.toBe(false);
            expect(h.finalize()).toBe(false);
        });

    test.each(VARIANTS)('%s - update after finalize is rejected (no state mutation)',
        (name, bs, oneShot, mod) => {
            const h = new mod.fn();
            h.update('finalised');
            h.finalize();
            // update returns this but logs warning ; the instance is locked.
            const before = h._bufLen;
            h.update('ignored');
            expect(h._bufLen).toBe(before);
        });

    test.each(VARIANTS)('%s - empty input streaming equals one-shot ""',
        (name, bs, oneShot, mod) => {
            const ref = toHex(oneShot(''));
            const h = new mod.fn();
            // No update call - finalize directly.
            expect(toHex(h.finalize())).toBe(ref);
        });

    test.each(VARIANTS)('%s - update accepts bitArray (HMAC ex-key path)',
        (name, bs, oneShot, mod) => {
            // HMAC builds inner/outer prefix as a bitArray of (block-size / 32) words
            // and pushes it as the very first update. Validate compatibility.
            const wordCount = bs / 32;
            const exKey = [];
            for (let i = 0; i < wordCount; i++) exKey.push(0x36363636 ^ i);
            // Should produce same digest whether passed as bitArray or as bytes.
            const asBytes = _ba.ba_to_ui8(exKey);
            const refStream = new mod.fn().update(asBytes).finalize();
            const baStream = new mod.fn().update(exKey).finalize();
            expect(toHex(refStream)).toBe(toHex(baStream));
        });
});
